function readTexGroup(text,start){if(text[start]!=='{')return null;let depth=0;for(let i=start;i<text.length;i++){if(text[i]==='{')depth++;else if(text[i]==='}'&&--depth===0)return{value:text.slice(start+1,i),end:i+1}}return null}
